import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"12. 常量、文字和枚举","description":"The Little Book of C 中文版 — 12. 常量、文字和枚举","frontmatter":{"title":"12. 常量、文字和枚举","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","02-语言基础","中文"],"description":"The Little Book of C 中文版 — 12. 常量、文字和枚举","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":12,"sidebarWeight":12,"alternateZh":"/posts/c教程/zh-CN/02-语言基础/012-Constants, Literals, and Enumerations","alternateEn":"/posts/c教程/en-US/02-Language Basics/012-Constants, Literals, and Enumerations"},"headers":[],"relativePath":"posts/c教程/zh-CN/02-语言基础/012-Constants, Literals, and Enumerations.md","filePath":"posts/c教程/zh-CN/02-语言基础/012-Constants, Literals, and Enumerations.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/02-语言基础/012-Constants, Literals, and Enumerations.md"};function i(l,a,o,c,d,r){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/02-Language Basics/012-Constants, Literals, and Enumerations)</p><p>C 程序通常依赖于在整个代码中使用的永不改变的值、数字、字符或命名常量。您可以给它们赋予有意义的名称，并保持程序的可读性、安全性和易于维护性，而不是到处散布神奇的数字。</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#define PI 3.14159</span><span>           // preprocessor constant</span></span>
<span class="line"><span>const int DAYS_IN_WEEK = 7;  // read-only variable</span></span>
<span class="line"><span>enum Direction { NORTH, EAST, SOUTH, WEST }; // enumerated constants</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Pi: %.2f\\n&quot;, PI);</span></span>
<span class="line"><span>    printf(&quot;Days in a week: %d\\n&quot;, DAYS_IN_WEEK);</span></span>
<span class="line"><span>    printf(&quot;Direction EAST has value: %d\\n&quot;, EAST);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pi: 3.14</span></span>
<span class="line"><span>Days in a week: 7</span></span>
<span class="line"><span>Direction EAST has value: 1</span></span></code></pre></div><h4 id="c-中的常量" tabindex="-1">C 中的常量 <a class="header-anchor" href="#c-中的常量" aria-label="Permalink to &quot;C 中的常量&quot;">​</a></h4><p>预处理器常数 (<code>#define</code>) 这些在编译前被替换。将它们视为文本替换，而不是变量。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define MAX_USERS 100</span></span>
<span class="line"><span>printf(&quot;Max users: %d\\n&quot;, MAX_USERS);</span></span></code></pre></div><ul><li>不使用内存。</li><li>没有类型检查，编译器只是替换文本。</li></ul><p>常量变量（<code>const</code>) 这些是存储在内存中的实际变量，但初始化后无法修改。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const double SPEED_OF_LIGHT = 299792458.0;</span></span></code></pre></div><ul><li>类型安全。</li><li>现代 C 代码中常量的首选。</li></ul><p>文字 这些是直接写入代码中的固定值：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>42          // integer literal</span></span>
<span class="line"><span>3.14        // floating-point literal</span></span>
<span class="line"><span>&#39;A&#39;</span><span>         // character literal</span></span>
<span class="line"><span>&quot;Hello&quot;</span><span>     // string literal</span></span>
<span class="line"><span>0xFF        // hexadecimal literal (255)</span></span>
<span class="line"><span>075         // octal literal (61)</span></span></code></pre></div><h4 id="枚举" tabindex="-1">枚举 <a class="header-anchor" href="#枚举" aria-label="Permalink to &quot;枚举&quot;">​</a></h4><p>枚举（enumeration 的缩写）定义了一组命名整型常量。它们使您的代码自我记录并防止原始数字出现错误。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enum TrafficLight {</span></span>
<span class="line"><span>    RED,     // 0</span></span>
<span class="line"><span>    YELLOW,  // 1</span></span>
<span class="line"><span>    GREEN    // 2</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    enum TrafficLight signal = GREEN;</span></span>
<span class="line"><span>    if (signal == GREEN)</span></span>
<span class="line"><span>        printf(&quot;Go!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>您还可以分配自定义值：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enum Month {</span></span>
<span class="line"><span>    JAN = 1, FEB, MAR, APR, MAY, JUN,</span></span>
<span class="line"><span>    JUL, AUG, SEP, OCT, NOV, DEC</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>现在<code>JAN</code>从 1 开始，每个值自动递增。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>常量和枚举使您的代码更清晰、更安全：</p><ul><li>您可以更改一个定义而不是多个数字。</li><li>编译器可以强制不修改常量。</li><li>枚举将相关值分组为有意义的集合。</li></ul><p>Without them, large programs become fragile and full of unexplained numbers, a maintenance nightmare.</p><p>优秀的 C 程序员使用常量来表达意图，而不仅仅是值。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>将旧程序中的每个数字文字替换为<code>#define</code>或者<code>const</code>。例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define MAX_SCORE 100</span></span>
<span class="line"><span>const float TAX_RATE = 0.08;</span></span></code></pre></div><p>创建一个<code>enum</code>一周中的几天，并打印<code>MONDAY</code>和<code>FRIDAY</code>.</p><p>在枚举中分配自定义值（例如以<code>SUNDAY = 1</code>).</p><p>实验：尝试改变<code>const int x = 5; x = 10;</code>，请注意编译器会阻止您修改它。</p><p>使用<code>printf</code>以不同格式打印文字值：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;%d %x %o\\n&quot;, 255, 255, 255); // decimal, hex, octal</span></span></code></pre></div><p>常量是让 C 程序清晰表达的方式。他们将数字转化为想法，这就是将代码从可用变为可理解的原因。</p>`,35)])])}const g=s(t,[["render",i]]);export{u as __pageData,g as default};
